-- Migration: 050_seed_associations
-- Seeds the default Associations & Federations directory content —
-- name, abbreviation, description, category and location for each of Uganda's
-- national sports associations/federations, matching the reference layout.

ON CONFLICT (id) DO UPDATE SET
  category = EXCLUDED.category,
  president = EXCLUDED.president,
  secretary = EXCLUDED.secretary,
  phone = EXCLUDED.phone,
  website_url = EXCLUDED.website_url;
