INSERT INTO cms_associations (id, name, slug, abbreviation, description, address, category, president, secretary, phone, website_url, sort_order, is_active) VALUES
  ('assoc_affu', 'American Football Federation of Uganda', 'american-football-federation-of-uganda', 'AFFU', 'AFFU is the national governing body for American football in Uganda, affiliated to the International Federation of American Football (IFAF).', 'Lugogo, Kampala', 'Ball Sports', '', '', '', '', 0, TRUE),
  ('assoc_auus', 'Association of Uganda University Sports', 'association-of-uganda-university-sports', 'AUUS', 'AUUS coordinates university-level sport in Uganda and is the affiliated FISU body for higher-education athletics.', 'Mengo, Kampala', 'Motorsports & Special', '', '', '', '', 1, TRUE),
  ('assoc_fmu', 'Federation of Motorsports Clubs of Uganda', 'federation-of-motorsports-clubs-of-uganda', 'FMU', 'FMU is the national governing body for motorsport in Uganda, affiliated to the FIA and FIM.', 'Lugogo, Kampala', 'Motorsports & Special', 'Moses Mucheri', 'Richard Okot', '+256 772 123456', 'https://fmu.co.ug', 2, TRUE),
  ('assoc_fuba', 'Federation of Uganda Basketball Associations', 'federation-of-uganda-basketball-associations', 'FUBA', 'FUBA is the governing body for basketball in Uganda, organising the National Basketball League and the She-Cranes and Silverbacks national teams.', 'Lugogo, Kampala', 'Ball Sports', 'Nasser Sserunjogi', 'Hudson Ssegamwenge', '+256 701 445566', 'https://fuba.ug', 3, TRUE),
